const menu=document.querySelector('.menu');const nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰';menu.setAttribute('aria-label','Open navigation')}));document.querySelectorAll('[data-interest]').forEach(a=>a.addEventListener('click',()=>{document.getElementById('interest').value=a.dataset.interest}));document.getElementById('enquiry').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const message=`Hello Vision Institute!\n\nMy name: ${data.get('name').trim()}\nPhone: ${data.get('phone').trim()}\nInterested in: ${data.get('interest')}\n${data.get('message').trim()?`\nMy goals: ${data.get('message').trim()}\n`:''}\nPlease share more details. Thank you!`;window.open('https://wa.me/919981790168?text='+encodeURIComponent(message),'_blank','noopener,noreferrer')});document.getElementById('year').textContent=new Date().getFullYear();if('IntersectionObserver' in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('motion');const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
const header=document.getElementById('header');const progress=document.querySelector('.scroll-progress');let ticking=false;window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{header.classList.toggle('fixed',window.scrollY>90);const max=document.documentElement.scrollHeight-window.innerHeight;progress.style.width=(max>0?window.scrollY/max*100:0)+'%';ticking=false});ticking=true}},{passive:true});
